const BSKY_HANDLE = "project-gamayun.bsky.social";const BSKY_FEED_API = "https://public.api.bsky.app/xrpc/app.bsky.feed.getAuthorFeed";function escapeFeedHtml(s){return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");}function formatFeedDate(iso){return new Date(iso).toISOString().replace("T", " ").slice(0, 16) + " UTC";}function renderMaintenanceEntry(entry){return `
    <div class="log-entry log-entry-maintenance">
      <div class="log-entry-tag">&gt; SYSTEM LOG</div>
      <p class="log-entry-text">${escapeFeedHtml(entry.text)}</p>
      <div class="bluesky-post-meta"><span>${entry.date}</span></div>
    </div>`;}function renderSocialEntry(item){const post = item.post ||{};const text = post.record && post.record.text ? post.record.text : "";const createdAt = post.record && post.record.createdAt ? post.record.createdAt : null;const author = post.author ||{};const rkey = (post.uri || "").split("/").pop();const permalink = author.handle && rkey ? `https://bsky.app/profile/${author.handle}/post/${rkey}` : `https://bsky.app/profile/${BSKY_HANDLE}`;let embedHtml = "";if (post.embed && Array.isArray(post.embed.images)){embedHtml = post.embed.images.map((img) => `<img src="${escapeFeedHtml(img.thumb || "")}" alt="${escapeFeedHtml(img.alt || "")}" style="max-width:100%; margin-top:0.5rem; border:1px solid var(--phosphor-dim);">` ).join("");}return `
    <div class="log-entry bluesky-post">
      <p class="bluesky-post-text">${escapeFeedHtml(text)}</p>
      ${embedHtml}
      <div class="bluesky-post-meta">
        ${createdAt ? `<span>${formatFeedDate(createdAt)}</span>` : ""}
        <span>&#128257; ${post.repostCount || 0}</span>
        <span>&#9829; ${post.likeCount || 0}</span>
        <a href="${permalink}" target="_blank" rel="noopener">&gt; view on bluesky</a>
      </div>
    </div>`;}async function loadLogFeed(){const container = document.getElementById("log-feed-container");if (!container) return;const maintenance = (typeof LOG_ENTRIES !== "undefined" ? LOG_ENTRIES : []).map((entry) => ({sortKey: entry.date, html: renderMaintenanceEntry(entry),}));let social = [];try{const res = await fetch(`${BSKY_FEED_API}?actor=${encodeURIComponent(BSKY_HANDLE)}&limit=30`);if (!res.ok) throw new Error(`API returned ${res.status}`);const data = await res.json();const feed = Array.isArray(data.feed) ? data.feed : [];social = feed.map((item) => ({sortKey: (item.post && item.post.record && item.post.record.createdAt) || "1970-01-01", html: renderSocialEntry(item),}));}catch (e){GAMA.log(`Bluesky feed fetch failed, showing maintenance log only: ${e.message}`);}const merged = [...maintenance, ...social].sort((a, b) => (a.sortKey < b.sortKey ? 1 : -1));if (!merged.length){container.innerHTML = '<p style="color:var(--phosphor-dim-text);">&gt; nothing logged yet.</p>';return;}container.innerHTML = merged.map((m) => m.html).join("");GAMA.log(`Log feed loaded: ${maintenance.length} system entr${maintenance.length === 1 ? "y" : "ies"}, ${social.length} post(s)`);}document.addEventListener("DOMContentLoaded", loadLogFeed);